import { createRequire } from 'node:module';
import { resolve } from 'node:path';

const require = createRequire(import.meta.url);
const commander = require(resolve('index.js'));
const Command = commander.Command;

const program = new Command();
let cmdValue;

program
  .version('0.0.1')
  .command('*')
  .description('test')
  .action(function (cmd) {
    cmdValue = cmd;
  });

program.parse(['node', 'test.js']);

if (typeof cmdValue !== 'undefined') {
  console.log('WHOBROKEIT_BUG: expected the "*" action not to run when no command is given, but it ran and received a command value');
  process.exitCode = 1;
} else {
  process.exitCode = 0;
}
